#****Begin: Generated Statements***
#****End: Generated Statements****

REA_length=LONG(TRIM(v3));
Start_REA=REA_length-4;
REA_RAW = SUBST(TRIM(V3),Start_REA,5);
Location=TRIM(V2);
REA= Location |REA_RAW;
REA2= Location | REA_RAW;

IF(TRIM(V1) @= 'A302.22086.R');
    V1='A302.22086.A.R';

ENDIF;


IF(SCAN('A.R',V1) <> 0);
     REA= TRIM(V2) | REA_RAW | 'REIMBURSED';

ENDIF;

IF(TRIM(V1) @= 'A302.20035.A.F');
     REA= TRIM(V2) | REA_RAW;

ENDIF;


Group_REA_Length=REA_length-3;
GROUP_REA_RAW = SUBST(TRIM(V3),Group_REA_Length,2);
AFE_NUM=TRIM(V4);
GROUP_REA= TRIM(V2) |SUBST(TRIM(V3),3,2);
AFE_UNIT_LENGTH=LONG(V1);
AFE_UNIT_START_LENGTH=AFE_UNIT_LENGTH-7;
AFE_UNITX=DELET(TRIM(V1),SCAN('.',TRIM(V1)), 1);
AFE_UNIT=SUBST(AFE_UNITX,7,1);

#--- Lookup Dewcription from WBS Element
V5 = ATTRS ( 'WBS Element', V3, 'Description');

PROJ_DESCRP=TRIM(V5);


#FUNDING= IF(SCAN('REIMBURSED',REA)<>0,'REIMBURSED',TRIM(V7));

IF ( v7 @= 'X');

        IF ( SCAN('REIMBURSED',REA)<>0 );

         FUNDING = 'FUNDED REIMBURSED';

         ELSE;
            
           FUNDING = 'FUNDED'; 
            
        ENDIF;
        
    ELSE;

        IF ( SCAN('REIMBURSED',REA)<>0 );

         FUNDING = 'UNFUNDED REIMBURSED ';

         ELSE;
            
           FUNDING = 'UNFUNDED';          
        ENDIF; 

ENDIF;
    
DATE_Length=LONG(TRIM(v8));
Year_DATE_Length=DATE_Length-3;
Month_DATE_Length=DATE_Length-5;
APPROVED_DATE= SUBST(TRIM(V8),Year_DATE_Length,2)|'/'|SUBST(TRIM(V8),Month_DATE_Length,2); 

IF(V6 @= '          ',ItemSkip,0);
Category_abbrev=CellGetS('transcat', V6, 'Category Code');

ENGR_RESP=TRIM(V9);


## Send Descriptions##


CellPutS(Location,'READATA',REA,'Location');

CellPutS(AFE_NUM,'READATA',REA,'AFE NUMBER');

IF(CellGETS('READATA',REA,'PROJ_DESC')@=' ');
CellPutS(PROJ_DESCRP,'READATA',REA,'PROJ_DESC');
else;
endif;

CellPutS(Category_abbrev,'READATA',REA,'Category Abbreviation');


CellPutS(FUNDING,'READATA',REA,'FUNDING');

if(DATE_Length<2); 
CellPutS('00/00','READATA',REA,'APPROVED_DATE');
else;
CellPutS(APPROVED_DATE,'READATA',REA,'APPROVED_DATE');
endif;

CellPutS(ENGR_RESP,'READATA',REA,'ENGR_RESP');





if(GROUP_REA @= '300BX'); 
CellPutS(CellGetS('groupid', GROUP_REA, 'GROUP DESCRIPTION'),'READATA',REA,'Group');
elseif(GROUP_REA @= '400SX'); 
CellPutS(CellGetS('groupid', GROUP_REA, 'GROUP DESCRIPTION'),'READATA',REA,'Group');
elseif(GROUP_REA @= '500PX');
CellPutS(CellGetS('groupid', GROUP_REA, 'GROUP DESCRIPTION'),'READATA',REA,'Group');
elseif(GROUP_REA @= '600CX');
CellPutS(CellGetS('groupid', GROUP_REA, 'GROUP DESCRIPTION'),'READATA',REA,'Group');
elseif(LOCATION@= '316' & AFE_UNIT@= '5');   
CellPutS('ARP','READATA',REA,'Group');
else;
CellPutS(CellGetS('groupid', Location, 'GROUP DESCRIPTION'),'READATA',REA,'Group');
endif;

CellPutS(ENGR_RESP,'READATA',REA,'ENGR_RESP');


#################################################################
###  SCANNING REA NUMBER FOR  "500M"  OR "50M"  IN PROJECT NAME WHICH WOULD
###  REFLECT GREATER THAN 0


Test1lessthan500M= IF(SCAN('500M',CellGETS('READATA',REA2,'PROJ_DESC')) > 0, 'Yes','No');

Test2lessthan500M= IF(SCAN('50M',CellGETS('READATA',REA2,'PROJ_DESC')) > 0, 'Yes','No');

Test3LessThan500M=IF(CELLGETN('AAQ2MMCK', REA2,CurrentYear, CurrentMonth, 'APPR AMT')<500000, 'Yes','No');

####################################################################


#####################################################################
###  UPDATE PERIODS BEGINNING OF NEW YEAR - EXAMPLE 2009

AMT_MAX1= MAX(CELLGETN('AAQ2MMCK', REA2,CurrentYear, CurrentMonth, 'APPR AMT'),
CELLGETN('AAQ2MMCK', REA2,CurrentYear, CurrentMonth, 'PLAN ' | CurrentYear ));

#####################################################################


######################################################################
###  JIM FACARO SAID TO CHANGE TO "TOT SPD EST" ON 02.11.09


##AMT_MAX2= MAX(CELLGETN('AAQ2MMCK', REA,CurrentYear, CurrentMonth, 'P-T-D'),
##(CELLGETN('AAQ2MMCK', REA,CurrentYear, CurrentMonth, 'O/L 2009')+
##CELLGETN('AAQ2MMCK', REA,CurrentYear, CurrentMonth, 'FCST 2010')+
##CELLGETN('AAQ2MMCK', REA,CurrentYear, CurrentMonth, 'FCST 2011')+
##CELLGETN('AAQ2MMCK', REA,CurrentYear, CurrentMonth, 'FCST 2012')));


AMT_MAX2= CELLGETN('AAQ2MMCK', REA2,CurrentYear, CurrentMonth, 'TOT SPD EST');




###############################################################


###############################################################
###  CODING FOR LESS THAN 500M  

if(Test3LessThan500M @= 'Yes' & MAX(AMT_MAX1,AMT_MAX2)<500000);
CellPutS('<500M','READATA',REA,'<500M');
elseif(Test1lessthan500M@='Yes');

CellPutS('<500M','READATA',REA,'<500M');
elseif(Test2lessthan500M@='Yes');

CellPutS('<500M','READATA',REA,'<500M');
else;
CellPutS('','READATA',REA,'<500M');
endif;
###############################################################

