             ENDIF;   
            
         # If Cost Center is not mapped  
         ELSE;

           DimensionElementInsertDirect ( 'SYS Headcount Cost Center', '', Cost_Center__Organization_Top, 'N');
            
           sCostCenter = 'Cost Center Undefined';

            # Send notification
            
           IF ( nErrCCCnt = 0 );
             AsciiOutPut ( sErrCCFile, 'Issue', 'EmployeeID','Employee Name','Position','Employee Type','Pay Group', 'Supervisor Organization', 'Division','Cost Center','Cost Center Percentage','Allocation Cost Center','Allocation Percentage' );       
