      IF ( PLAccount @= '70080999');

          #--- Skip, do nothting

        ELSE;  
          
        sText = CellGetS ( sSrcCube, Period, FunctionalArea, Plant, ProfitCenter, CostCenter, PLAccount, DocumentNo, 'Text' )  ; 

         IF ( sText @= '' % SUBST( sText , 4,1) @<> '-' ); 

