            ELSEIF ( SUBST ( sText,1,7) @= 'Columbia');

             sTask = 'NOT DESIGNATED';
             sPhase = '0000';

            ELSE;
             
             sTask = SUBST ( sText, 1, 3 ) ;
             sPhase = SUBST ( sText, 5, 4 ) ;

         ENDIF;

       DimensionElementInsert ( 'Glenn Springs Task', '', sTask, 'N'); 
       DimensionElementInsert ( 'Glenn Springs Phase', '', sPhase, 'N');         

       DimensionElementComponentAdd ( 'Glenn Springs Task', 'All Task', sTask, 1 );
       DimensionElementComponentAdd ( 'Glenn Springs Phase', 'All Phase', sPhase, 1 );

#--- Requested Logic 9/12/2024
       DimensionElementInsert ( 'Glenn Springs Account', '', PLAccount, 'N') ;
       DimensionElementComponentAdd ( 'Glenn Springs Account', 'Expenditures', PLAccount, 1 );        
        
      ENDIF;   

    ENDIF;    

