 'pSuppressConsol',1,
 'pSuppressRules', 1,
 'pDimensionDelim', '^',
 'pElementStartDelim', ':',
 'pElementDelim', '>',
 'pDebug', 0 );

 #-- Filter Fiscal Periods to load
