sEndPeriodIx = ATTRS ( sDim, sEndPeriod, 'Period Index');
nEndPeriodIx = StringToNumber ( sEndPeriodIx );

ix = nStartPeriodIx;

  WHILE ( ix <= nEndPeriodIx );

      SubsetElementInsert ( sDim, sSrcView, NumberToString(ix), 1 );

 ix = ix + 1;
      
END;   


SubsetDeleteAllElements ( 'mBalance Sheet Detail', sSrcView );

SubsetElementInsert ( 'mBalance Sheet Detail', sSrcView , 'All Measures (System)', 1);

ViewExtractSkipCalcsSet( sSrcCube, sSrcView, 0 );


