ExecuteProcess ( 'Sys_Cube_View_Create',
'pCube', sTgtCube,
 'pView', sTgtView,
 'pFilter', sTgtFilter,
 'pSuppressZero', 1,
 'pSuppressConsol',1,
 'pSuppressRules', 1,
 'pDimensionDelim', '^',
 'pElementStartDelim', ':',
 'pElementDelim', '>',
 'pDebug', 0 );

#-- Filter Fiscal Periods to load
