 'pFilter', sTgtFilter2,
 'pSuppressZero', 1,
 'pSuppressConsol',1,
 'pSuppressRules', 1,
 'pDimensionDelim', '^',
 'pElementStartDelim', ':',
 'pElementDelim', '>',
