 AttrPutS (sMaterialCap, 'Manufacturing Cost Object', sMaterialCons, 'CAPTION' );   


nNumerator = 0;
nDenominator = 0;
nAlloc = 0;
nValue = 0;

 ix = 1;

  WHILE ( ix <= nNumberOfOrders );
    
      sProductionOrder = CellGetS ( 'SYS Production Order', 'Actual', sPeriod, WERKS, sMaterial, NumberToString ( ix ), 'Production Order' );

      nActQtyCheck = CellGetN ( sTgtCube, 'Actual', sPeriod, 'All Production Activities', WERKS, 'Total mfg costs (Excl Transferred Costs)', sMaterialCons, 'All Production Order', sMaterial, 'Actual Qty' );
      
      nNumerator = CellGetN ( sTgtCube, 'Actual', sPeriod, 'All Production Activities', WERKS, 'Total mfg costs (Excl Transferred Costs)', sMaterialCons, sProductionOrder, sMaterial, 'Actual Qty' );
      nDenominator = CellGetN ( sTgtCube, 'Actual', sPeriod, 'All Production Activities', WERKS, 'Total mfg costs (Excl Transferred Costs)', sMaterialCons, 'All Production Order', sMaterial, 'Actual Qty' );
      
     #--- IF Component Actual Qty = 0, use production Actual Qty
      IF ( nActQtyCheck = 0 );

       nNumerator = CellGetN ( sTgtCube, 'Actual', sPeriod, 'All Production Activities', WERKS, 'Production', sMaterial, sProductionOrder, sMaterial, 'Actual Qty' );
       nDenominator = CellGetN ( sTgtCube, 'Actual', sPeriod, 'All Production Activities', WERKS, 'Production', sMaterial,  'All Production Order', sMaterial, 'Actual Qty' );          

      ENDIF;
   
      nAlloc = nNumerator \ nDenominator;




IF ( SCAN ('-', FIX_COST ) <> 0 );
    
    sFixCost = SUBST( FIX_COST, 1, long( FIX_COST )-1 );
    nFixCost = StringToNumber ( sFixCost ) * -1;

    ELSE;
    
    nFixCost = StringToNumber ( FIX_COST );
    
ENDIF;  

IF ( SCAN ('-', VAR_COST ) <> 0 );
    
    sVarCost = SUBST( VAR_COST, 1, long( VAR_COST )-1 );
    nVarCost = StringToNumber ( sVarCost ) * -1;

    ELSE;
    
    nVarCost = StringToNumber ( VAR_COST );
    
ENDIF;  

## Added per Marquis Owens on 05/06/2026
## Skip records with Item Type "UP" and Category "ZU"
## These records post variances to material ledger

IF(PSART @= 'UP' & CATEGORY @='ZU');
    itemskip;

ENDIF;
      
    nValue = ( nFixCost + nVarCost ) * nAlloc;
      
    CellIncrementN ( nValue, sTgtCube, 'Actual', sPeriod, 'All Production Activities', WERKS, COST_GROUP, sMaterialCons, sProductionOrder, sMaterial, 'Actual Cost' );


 ix = ix + 1;
END;

