#--------------------------------------------------------
#--- Process loads the Plant Assessments
# Filters: Functional Area: 687 & PL Accoumts: Assessments
#--- Created: 09/09/2024
#### -- Changes:
# --- 11/18/2024 - Integrate changes to the Profit and Loss Detail cube
#--------------------------------------------------------


MinorErrorLogMax=-1;
sSrcCube = 'Profit and Loss Detail';
sTgtCube = 'Plant Assessment';
CellPutS('NO', '}CubeProperties', sTgtCube, 'LOGGING');


sProc = GetProcessName();
sRand = NumberToString(Round(RAND()*1000));


IF ( pStartPeriod @= '' );
    
   sStartPeriod = CellGetS ( 'SYS Control', 'Close Period', 'String' );

   sEndPeriod = ATTRS ( 'Fiscal Period', sStartPeriod, 'Next Period');

 ELSEIF ( pStartPeriod @<> '' );

    sStartPeriod = pStartPeriod;

    IF ( pEndPeriod @='' );

        ProcessQuit();

        ELSE;
    
       sEndPeriod =  pEndPeriod ;

    ENDIF;
        
 ELSE;

    ProcessQuit();

ENDIF;

#---- Create Source View
sSrcView = '}SYS_Src_' |sProc|'_'| sRand;

sSrcFilter = 
  '  Fiscal Period: ' | sStartPeriod | '
   ^ Functional Area: All Functional Area
   ^ Plant: All Plant
   ^ Profit Center: All Profit Center
   ^ Cost Center: All Cost Center   
   ^ PL Account: ASSESSMENT
   ^ Document No: All Document No
   ^ mProfit and Loss Detail: USD > Sender Cost Center > Text > Order';

ExecuteProcess ( 'Sys_Cube_View_Create',
'pCube', sSrcCube,
 'pView', sSrcView,
 'pFilter', sSrcFilter,
 'pSuppressZero', 1,
 'pSuppressConsol',1,
 'pSuppressRules', 1,
 'pDimensionDelim', '^',
 'pElementStartDelim', ':',
 'pElementDelim', '>',
 'pDebug', 0 );


#--- Filter only tagged Functional Areas to be loaded in Manufacturing cube
sDim = 'Functional Area';
SubsetDeleteAllElements ( sDim, sSrcView );

ix = 1;

  WHILE ( ix <= ELCOMPN (sDim, 'All Functional Area' ) );

      sFA = ELCOMP ( sDim, 'All Functional Area', ix );
      sBTLFA = ATTRS ( sDim, sFA, 'Fixed Manufacturing Cost (System)' );

      IF ( sBTLFA @<> '' );

          SubsetElementInsert ( sDim, sSrcView, sFA, 1 );

      ENDIF;    

 ix = ix + 1;

END;      


#-- Filter Fiscal Periods to load
sDim = 'Fiscal Period';
SubsetDeleteAllElements( sDim, sSrcView );

sStartPeriodIx = ATTRS ( sDim, sStartPeriod, 'Period Index');
nStartPeriodIx = StringToNumber ( sStartPeriodIx );

sEndPeriodIx = ATTRS ( sDim, sEndPeriod, 'Period Index');
nEndPeriodIx = StringToNumber ( sEndPeriodIx );

ix = nStartPeriodIx;

  WHILE ( ix <= nEndPeriodIx );

      SubsetElementInsert ( sDim, sSrcView, NumberToString(ix), 1 );

 ix = ix + 1;
      
END;

#---- Assign Source View as TI data source
DataSourceType = 'VIEW';
DataSourceNameForServer = sSrcCube;
DataSourceNameForClient = sSrcCube;
DataSourceCubeView = sSrcView;


#---- Target View: Below the line Assessments
sTgtView = '}SYS_Tgt_' |sProc|'_'| sRand;


sTgtFilter = 
  'Scenario: Actual
   ^ Fiscal Period: ' | sStartPeriod | '
   ^ Cost Center: All Cost Center
   ^ Plant Assessment Cost Object: All Plant Assessment Cost Object
   ^ PL Account: All PL Account 
   ^ Assessment Segment: All Assessment Segment
   ^ mPlant Assessment: USD ';


#---- Create Target View
ExecuteProcess ( 'Sys_Cube_View_Create',
'pCube', sTgtCube,
 'pView', sTgtView,
 'pFilter', sTgtFilter,
 'pSuppressZero', 1,
 'pSuppressConsol',1,
 'pSuppressRules', 1,
 'pDimensionDelim', '^',
 'pElementStartDelim', ':',
 'pElementDelim', '>',
 'pDebug', 0 );

#-- Filter Fiscal Periods to load
sDim = 'Fiscal Period';
SubsetDeleteAllElements( sDim, sTgtView );

sStartPeriodIx = ATTRS ( sDim, sStartPeriod, 'Period Index');
nStartPeriodIx = StringToNumber ( sStartPeriodIx );

sEndPeriodIx = ATTRS ( sDim, sEndPeriod, 'Period Index');
nEndPeriodIx = StringToNumber ( sEndPeriodIx );

ix = nStartPeriodIx;

  WHILE ( ix <= nEndPeriodIx );

      SubsetElementInsert ( sDim, sTgtView, NumberToString(ix), 1 );

 ix = ix + 1;
      
END;  

ViewZeroOut ( sTgtCube, sTgtView );

