#****Begin: Generated Statements***
#****End: Generated Statements****
#--------------------------------------------------------
#--- Seed Actual Scenario into Outlook Scenario
#--- Created: 07/08/2024
#### -- Changes:
# --- 11/15/24 - Load period to key-off Closed Period system control or based on start- and end period parameters
#--------------------------------------------------------

MinorErrorLogMax=-1;
sSrcCube = 'Profit and Loss';
sTgtCube = 'Profit and Loss';
sTgtCube2 = 'Manual Input';


sUser = TM1User();
nGMTOffSet = CellGetN('SYS Control', 'GMT Offset', 'Numeric' ) ;
sDateTime = TIMST( Now() - (nGMTOffset/24), '\Y-\m-\d \H:\i \p');


sProc = GetProcessName();
sRand = NumberToString(Round(RAND()*1000));

IF ( pStartPeriod @= '' );
    
   sStartPeriod = CellGetS ( 'SYS Control', 'Close Period', 'String' );

   sEndPeriod = sStartPeriod;

 ELSEIF ( pStartPeriod @<> '' );

    sStartPeriod = pStartPeriod;

    IF ( pEndPeriod @='' );

        ProcessQuit();

        ELSE;
    
       sEndPeriod =  pEndPeriod ;

    ENDIF;
        
 ELSE;

    ProcessQuit();

ENDIF;


#---- Create Source View
sSrcView = '}SYS_Src_' |sProc|'_'| sRand;

sSrcFilter = 
  'Scenario: Actual
   ^ Fiscal Period: ' | sStartPeriod | '
   ^ Plant: All Plant
   ^ Functional Area: All Functional Area
   ^ Profit Center: All Profit Center
   ^ PL Account: All PL Account 
   ^ Material: All Material
   ^ Profit and Loss Source: Actual Data Sources (Ex Freight Reclass)
   ^ mProfit and Loss: USD';



ExecuteProcess ( 'Sys_Cube_View_Create',
'pCube', sSrcCube,
 'pView', sSrcView,
 'pFilter', sSrcFilter,
 'pSuppressZero', 1,
 'pSuppressConsol',1,
 'pSuppressRules', 1,
 'pDimensionDelim', '^',
 'pElementStartDelim', ':',
 'pElementDelim', '>',
 'pDebug', 0 );

sFcstPeriodCheck = '';

#-- Filter Fiscal Periods to load
sDim = 'Fiscal Period';
SubsetDeleteAllElements( sDim, sSrcView );

sStartPeriodIx = ATTRS ( sDim, sStartPeriod, 'Period Index');
nStartPeriodIx = StringToNumber ( sStartPeriodIx );

sEndPeriodIx = ATTRS ( sDim, sEndPeriod, 'Period Index');
nEndPeriodIx = StringToNumber ( sEndPeriodIx );

ix = nStartPeriodIx;

  WHILE ( ix <= nEndPeriodIx );

      SubsetElementInsert ( sDim, sSrcView, NumberToString(ix), 1 );
#     --- Check if period is a OL Period
      IF ( ELISANC ( sDim, 'Outlook Periods', NumberToString(ix) ) = 1 );
          
       sFcstPeriodCheck = 'Y';
          
      ENDIF;    
      
 ix = ix + 1;
      
END; 

#-- Quit process if period includes forecast periods.
IF ( sFcstPeriodCheck @= 'Y' );
    ProcessQuit();
ENDIF;


sDim = 'Functional Area';
SubsetDeleteAllElements ( sDim, sSrcView );

ix = 1;

  WHILE ( ix <= ELCOMPN (sDim, 'All Functional Area' ) );

      sFA = ELCOMP ( sDim, 'All Functional Area', ix );
      sFAReclass = ATTRS ( sDim, sFA, 'Freight Reclass' );

      IF ( sFAReclass @<> '' );

          SubsetElementInsert ( sDim, sSrcView, sFA, 1 );

      ENDIF;    

 ix = ix + 1;

END;    


sDim = 'Material';
SubsetDeleteAllElements ( sDim, sSrcView );
SubsetElementInsert ( sDim, sSrcView, 'All Material', 1 );

sDim = 'ProfitCenter';
SubsetDeleteAllElements ( sDim, sSrcView );
SubsetElementInsert ( sDim, sSrcView, 'All Profit Center', 1 );

sDim = 'Plant';
SubsetDeleteAllElements ( sDim, sSrcView );
SubsetElementInsert ( sDim, sSrcView, 'All Plant', 1 );

ViewExtractSkipCalcsSet( sSrcCube, sSrcView, 0 );




#---- Assign Source View as TI data source
DataSourceType = 'VIEW';
DataSourceNameForServer = sSrcCube;
DataSourceNameForClient = sSrcCube;
DataSourceCubeView = sSrcView;


#---- Target View: Below the line Assessments
sTgtView = '}SYS_Tgt_' |sProc|'_'| sRand;

sTgtFilter = 
  'Scenario: Actual
   ^ Fiscal Period:  ' | sStartPeriod | '
   ^ Plant: All Plant
   ^ Functional Area: All Functional Area
   ^ Profit Center: All Profit Center
   ^ PL Account: All PL Account 
   ^ Material: All Material
   ^ Profit and Loss Source: Freight Reclass
   ^ mProfit and Loss: USD > Local';


#---- Create Target View
ExecuteProcess ( 'Sys_Cube_View_Create',
'pCube', sTgtCube,
 'pView', sTgtView,
 'pFilter', sTgtFilter,
 'pSuppressZero', 1,
 'pSuppressConsol',1,
 'pSuppressRules', 1,
 'pDimensionDelim', '^',
 'pElementStartDelim', ':',
 'pElementDelim', '>',
 'pDebug', 0 );

#-- Filter Fiscal Periods to load
sDim = 'Fiscal Period';
SubsetDeleteAllElements( sDim, sTgtView );

sStartPeriodIx = ATTRS ( sDim, sStartPeriod, 'Period Index');
nStartPeriodIx = StringToNumber ( sStartPeriodIx );

sEndPeriodIx = ATTRS ( sDim, sEndPeriod, 'Period Index');
nEndPeriodIx = StringToNumber ( sEndPeriodIx );

ix = nStartPeriodIx;

  WHILE ( ix <= nEndPeriodIx );

      SubsetElementInsert ( sDim, sTgtView, NumberToString(ix), 1 );
      
 ix = ix + 1;
      
END;


