procedures.Epilog:
#****Begin: Generated Statements***
#****End: Generated Statements****

CellPutS ( sTransLog,  '}CubeProperties', pCube, 'LOGGING');

## ------------- Start: Delete Process Views and Subsets
sProcExit = 'Sys_Cube_ViewAndSubsets_Delete';
sProcSubsetDelete = 'Sys_Dim_Sub_Delete';
# Clear Target View and Subsets
 ExecuteProcess ( sProcExit, 'pCube', sCube, 'pView', sViewTgt, 'pSubset', sViewTgt, 'pMode' , 1, 'pDebug', 0);
 ExecuteProcess ( sProcExit, 'pCube', sCube, 'pView', sViewSrc, 'pSubset', sViewSrc, 'pMode' , 1, 'pDebug', 0);

procedures.Prolog:
#****Begin: Generated Statements***
#****End: Generated Statements****


#--- Prevent process running
#- Start period but no end period
#- End period with no start period
IF ( pStartPeriod @<> '' & pEndPeriod @= '' );
 ProcessError;
ELSEIF ( pStartPeriod @= '' & pEndPeriod @<> '' );
 ProcessError;
ENDIF;

#- Source and target scenario is the same
IF ( pSrcVersion @= pTgtVersion );
 ProcessError;   
ENDIF;

#- Target version is Outlook and Start - & end period are actualized  / historical months
sCurClosePeriod = CellgetS ( 'SYS Control', 'Close Period', 'String');
sCurCloseIx = ATTRS ( 'Fiscal Period', sCurClosePeriod, 'Period Index');
nCurClosePeriod = StringToNumber ( sCurCloseIx );

sStartIx = IF ( pStartPeriod @<> '', ATTRS ( 'Fiscal Period', pStartPeriod, 'Period Index'), '0');
sEndIx = IF ( pEndPeriod @<> '', ATTRS ( 'Fiscal Period', pEndPeriod, 'Period Index'), '0');
nStartIx = StringToNumber ( sStartIx );
nEndIx = StringToNumber ( sEndIx );
sTgtVersion = DimensionElementPrincipalName( 'Scenario', pTgtVersion );

IF( sTgtVersion @= 'Outlook' & ( nStartIx <= nCurClosePeriod % nEndIx <= nCurClosePeriod ));
# ProcessError;   
ENDIF;

sTransLog = CellGetS ( '}CubeProperties', pCube, 'LOGGING');
CellPutS ( 'NO',  '}CubeProperties', pCube, 'LOGGING');


MinorErrorLogMax=-1;







#Count Number of Dimensions
nDimCnt = 1;
WHILE (TabDim(pCube, nDimCnt) @<> '');
   nDimCnt = nDimCnt + 1;
END;
nDimCnt = nDimCnt - 1;



sMeasureDim = TabDim ( pCube, nDimCnt );
MeasureFilter = '';


ix = 1;

   WHILE ( ix <= DIMSIZ ( sMeasureDim ) );

   vElem = DIMNM ( sMeasureDim, ix ) ;

   IF ( DTYPE ( sMeasureDim , vElem ) @= 'S' );

   MeasureFilter = MeasureFilter | ' > ' | vElem ;

  ENDIF;

 ix = ix + 1;

END;


isStringPresent = 'no';
IF( TRIM(MeasureFilter) @<> '');
isStringPresent = 'yes';
EndIf;


IF(isStringPresent @= 'no');
 ProcessBreak();
ENDIF;


MeasureFilter = SUBST ( MeasureFilter, 4, LONG ( MeasureFilter) - 3 );



sCube = pCube;
sProc = GetProcessName();
sRndNo = NumberToString(Int(Rand() * 1000));



nCharSrc = Scan ('/', pSrcVersion);

IF ( nCharSrc <> 0 );
sSrcVersion = SUBST( pSrcVersion,1,nCharSrc -1 ) | SUBST( pSrcVersion,nCharSrc +1, long(pSrcVersion) -1 );
else;
    sSrcVersion = pSrcVersion;
ENDIF;
    
nCharTgt = Scan ('/', pTgtVersion);
IF ( nCharTgt <> 0 );
sTgtVersion = SUBST( pTgtVersion,1,nCharTgt -1) | SUBST( pTgtVersion,nCharTgt +1, long(pTgtVersion) -1 );
else;
    sTgtVersion = pTgtVersion;
ENDIF;

sViewSrc = '}SYS_Src' | sProc | '_' | pCube | '_' | sSrcVersion | '_' |  sTgtVersion | '_' | pStartPeriod | '_' | pEndPeriod | '_' | sRndNo;


sFilter =  
   'Scenario: ' | pSrcVersion | '
   ^ Fiscal Period: All Year
   ^ ' | sMeasureDim | ': ' | MeasureFilter ;



sProcView = 'Sys_Cube_View_Create';

# Create Source View

ExecuteProcess( sProcView,
    'pCube', sCube,
    'pView', sViewSrc, 
    'pFilter', sFilter, 
    'pSuppressZero', 1 , 
    'pSuppressConsol',0, 
     'pSuppressRules', 0, 
     'pDimensionDelim', '^', 
       'pElementSTartDelim', ':', 
       'pElementDelim', '>', 
   'pDebug',0 );


#Assign Source View as DataSource
DATASOURCETYPE='VIEW';
DATASOURCENAMEFORSERVER= sCube;
DATASOURCENAMEFORCLIENT= sCube;
DATASOURCECUBEVIEW=sViewSrc;


sViewTgt = '}SYS_Tgt_'  | sProc | '_' | pCube | '_' | sSrcVersion | '_' |  sTgtVersion | '_' | pStartPeriod | '_' | pEndPeriod | '_' | sRndNo;

sFilter =  
   'Scenario: ' | pTgtVersion  | '
   ^ Fiscal Period: All Year
   ^ ' | sMeasureDim | ': ' | MeasureFilter ;

  
# Create Target View and Clear Out Slice

ExecuteProcess( sProcView,
    'pCube', sCube,
    'pView', sViewTgt, 
    'pFilter', sFilter, 
    'pSuppressZero', 1 , 
    'pSuppressConsol',0, 
     'pSuppressRules', 1, 
     'pDimensionDelim', '^', 
       'pElementSTartDelim', ':', 
       'pElementDelim', '>', 
   'pDebug',0 );

sDim = 'Fiscal Period';
SubsetDeleteAllElements ( sDim, sViewTgt );

IF ( pStartPeriod @= '' & pEndPeriod @= '' );
    
   sCurrentYear = CellGetS ( 'SYS Control', 'Current Fiscal Year', 'String' );

   ix = 1; 
    
     WHILE ( ix <= DIMSIZ ( sDim ) );

        sElem = DIMNM ( sDim, ix );

          IF (  ELISANC ( sDim, sCurrentYear, sElem ) = 1 );

            SubsetElementInsert ( sDim, sViewTgt, sElem, 1 );

          ENDIF;
        
    ix = ix + 1;
        
  END;      

 ELSEIF ( pStartPeriod @<> '' & pEndPeriod @<> '' );

    ix = nStartIx;

         WHILE ( ix <= nEndIx );

           SubsetElementInsert ( sDim, sViewTgt, NumberToString ( ix ), 1 );

     ix = ix + 1;
             
    END;    
    
  ENDIF; 

ViewZeroOut ( sCube, sViewTgt );





# Determine dimensions in source cube 
sDim1 = TabDim( pCube, 1 );
sDim2 = TabDim( pCube, 2 );
sDim3 = TabDim( pCube, 3 );
sDim4 = TabDim( pCube, 4 );
sDim5 = TabDim( pCube, 5 );
