#--------------------------------------------------------
#--- Process Updates the SYS BS Account dimension and attributes
#--- Created: 05/24/2024
#### -- Changes:
# 1.) 08/07/2024 - Update Process to key-off from SAP File
# 2.) 08/07/2024 - Logic to remove leading zeros
# 3.) 08/08/2024 - Update process to key off Hierarchy Control cube
# 4.) 10/21/2024 - Alpha numeric range logic
#--------------------------------------------------------

sDim = 'SYS BS Account Hierarchy';
sBSDim = 'BS Account';
sDimLineNo = 'SYS BS Account Hierarchy LineNo';
sCube = 'SYS BS Account Hierarchy';

MinorErrorLogMax= -1;
CellPutS('NO', '}CubeProperties', '}ElementAttributes_' | sDim, 'LOGGING');

# Source file

sSourceFolder = CellGetS( 'SYS Control', 'Source Folder', 'String' );

sSourceFile = sSourceFolder | pFile;

DataSourceNameForServer = sSourceFile;

# Clear Cube
CubeClearData( sCube );
CubeClearData( '}ElementAttributes_' | sDim );
Dimensiondeleteallelements ( sDim );


nLine = 0;

# Number of Hierarchies Defined
nHier = CellGetN ( 'SYS Hierarchy Control', sBSDim, 'All Hierarchies', 'Count (System)' );


# Add Hierarchy ID Alias to the SYS BS Account Hierarchy dimension (reference dimension)
ix = 1;

 WHILE ( ix <= nHier );

     sIx = NumberToString ( ix) ;

     sSource = CellGetS ( 'SYS Hierarchy Control', sBSDim, sIx, 'Source' );

     IF ( sSource @= 'SAP');

      sHierName = CellGetS ( 'SYS Hierarchy Control', sBSDim, sIx, 'Hierarchy Name' );   

      IF ( DIMIX ( '}ElementAttributes_'|sDim , sHierName ) = 0 ); 

        AttrInsert ( sDim, '', sHierName | ' ID', 'A');
      
      ENDIF;  
         
     ENDIF;
     
 ix = ix + 1;
     
END;

procedures.Data:
#****Begin: Generated Statements***
#****End: Generated Statements****


# Reset the  LOOP variables
sProcess = '';
sSource = '';
sHierName = '';

# Look through the SYS Hierarchy Control and setermine if Hierarchy defined in the cube is maintained from SAP
# If True ( sProcess @= 'Y') the hierarchy will be maintained
ix = 1;

 WHILE ( ix <= nHier );

     sIx = NumberToString ( ix) ;

     sSource = CellGetS ( 'SYS Hierarchy Control', sBSDim, sIx, 'Source' );

     IF ( sSource @= 'SAP');

      sHierName = CellGetS ( 'SYS Hierarchy Control', sBSDim, sIx, 'Hierarchy Name' );   

      IF( sHierName @= VERSN )   ;

       sProcess = 'Y';
          
       ix = nHier;   

      ENDIF;
         
     ENDIF;
     
 ix = ix + 1;
END;     



IF ( sProcess @= 'Y');


    # Insert new Item elements
DimensionElementInsertDirect ( sDim, '', ERGSL, 'n');

    sID = VERSN | '_' | ID;

       ATTRPUTS ( sID, sDim, ERGSL, sHierName | ' ID');


    
    
#--- Derive Line Numbers against which data will be loaded
nLine = CellGetN ( sCube, ERGSL, 'All Lines', 'Count (System)') + 1;
sLine = NumberToString ( nLine );





# Add rows to the LineNo dimension
DimensionElementInsertDirect( sDimLineNo, '', sLine, 'N' );
DimensionElementComponentAddDirect( sDimLineNo, 'All Lines', sLine , 1);


# Trim leading Zero's

#-- VONKT
nCount = 0;
sVONKT = '';

ix = 1;
  WHILE ( ix <= LONG ( VONKT ) );
      IF ( SUBST (VONKT, ix , 1 ) @= '0' );

          nCount = nCount + 1;

      else;
       ix  = 999999;
      endif;    

 ix = ix+ 1;
end;

IF ( nCount > 0 );
   sVONKT = DELET ( VONKT, 1, nCount );
 ELSE;
    sVONKT =  VONKT;
    
 ENDIF;  

##---- Identify Alpha Positions from the trimmed From Account string
nCount = 0;    
nAlphaCount = 0;
#-- sVONKT
ix = 1;
  WHILE ( ix <= LONG ( sVONKT ) );
      IF ( CODE ( sVONKT, ix  ) < 48 % CODE ( sVONKT, ix  ) > 57 );

          nCount = ix ;

           nAlphaCount = CellGetN ( sCube, ERGSL, sLine, 'From Alpha Position Count (System)' ) + 1;

            CellPutS ( NumberToString( nCount ), sCube, ERGSL, sLine,  'From Alpha Position ' | NumberToString( nAlphaCount ) );

            CellPutS ( NumberToString( CODE ( sVONKT, ix  ) ), sCube, ERGSL, sLine,  'From Ascii ' | NumberToString( nAlphaCount ) );

            CellPutS (  SUBST ( sVONKT, ix, 1  ) , sCube, ERGSL, sLine,  'From Alpha ' | NumberToString( nAlphaCount ) );          
          
      endif;    

 ix = ix+ 1;
end;



    

#-- BISKT
nCount = 0;
sBISKT = '';

ix = 1;
  WHILE ( ix <= LONG ( BISKT ) );
      IF ( SUBST (BISKT, ix , 1 ) @= '0' );

          nCount = nCount + 1;

      else;
       ix  = 999999;
      endif;    

 ix = ix+ 1;
end;

IF ( nCount > 0 );
   sBISKT = DELET ( BISKT, 1, nCount );
 ELSE;
    sBISKT =  BISKT;
    
 ENDIF;  


##---- Identify Alpha Positions from the trimmed To Account string
nCount = 0;    
nAlphaCount = 0;
#-- sBISKT
ix = 1;
  WHILE ( ix <= LONG ( sBISKT ) );
      IF ( CODE ( sBISKT, ix  ) < 48 % CODE ( sBISKT, ix  ) > 57 );

          nCount = ix ;

           nAlphaCount = CellGetN ( sCube, ERGSL, sLine, 'To Alpha Position Count (System)' ) + 1;

            CellPutS ( NumberToString( nCount ), sCube, ERGSL, sLine,  'To Alpha Position ' | NumberToString( nAlphaCount ) );

            CellPutS ( NumberToString( CODE ( sBISKT, ix  ) ), sCube, ERGSL, sLine,  'To Ascii ' | NumberToString( nAlphaCount ) );

            CellPutS (  SUBST ( sBISKT, ix, 1  ) , sCube, ERGSL, sLine,  'To Alpha ' | NumberToString( nAlphaCount ) );          
          
      endif;    

 ix = ix+ 1;
end;

    
    
# Update Cube Values
CellPutS ( sVONKT, sCube, ERGSL, sLine, 'From Value' );
CellPutS ( sBISKT, sCube, ERGSL, sLine, 'To Value' );

ENDIF;

