#--------------------------------------------------------
#--- Process Updates the SYS_PL_Account dimension and attributes
#--- Created: 05/17/2024
#### -- Changes:
# 1.) 08/07/2024 - Update Process to key-off from SAP File
# 2.) 08/07/2024 - Logic to remove leading zeros
# 3.) 08/09/2024 - Update Process to create Stage Hiearchy
# 4.) 09/06/2024 - Not all element are rolling up into hiearchies - DEPR Example
#--------------------------------------------------------

sDim = 'SYS PL Account Hierarchy';
sDimLineNo = 'SYS PL Account Hierarchy LineNo';
sCube = 'SYS PL Account Hierarchy';

MinorErrorLogMax= -1;
CellPutS('NO', '}CubeProperties', '}ElementAttributes_' | sDim, 'LOGGING');

# Source file

sSourceFolder = CellGetS( 'SYS Control', 'Source Folder', 'String' );

sSourceFile = sSourceFolder | pFile;

DataSourceNameForServer = sSourceFile;


DimensionDeleteAllElements( sDim );



# Clear Cube & attributes
CubeClearData( sCube );
CubeClearData( '}ElementAttributes_' | sDim );

AttrInsert ( sDim, '', 'Description', 'S');

nLine = 0;

