#****Begin: Generated Statements***
#****End: Generated Statements****


IF (VALSIGN @= 'I' );
    
 DimensionElementInsert ( sDim, '', SUBSETNAME, 'N' );

 ELSE;

 DimensionElementInsert ( sDim, '', SUBSETNAME, 'C' );   

ENDIF;

DimensionElementInsert ( sDim, '', SETNAME, 'C' );  
DimensionElementComponentAdd( sDim, SETNAME, SUBSETNAME, 1 );

procedures.Data:
#****Begin: Generated Statements***
#****End: Generated Statements****




#--- Derive Line Numbers against which data will be loaded
nLine = CellGetN ( sCube, SUBSETNAME, 'All Lines', 'Count (System)') + 1;
sLine = NumberToString ( nLine );

#Trim leading Zero's

#-- VALFROM
nCount = 0;
sVALFROM = '';

ix = 1;
  WHILE ( ix <= LONG ( VALFROM ) );
      IF ( SUBST (VALFROM, ix , 1 ) @= '0' );

          nCount = nCount + 1;

      else;
       ix  = 999999;
      endif;    

 ix = ix+ 1;
end;

IF ( nCount > 0 );
   sVALFROM = DELET ( VALFROM, 1, nCount );
 ELSE;
    sVALFROM =  VALFROM;
    
 ENDIF;  

#-- VALTO
nCount = 0;
sVALTO = '';

ix = 1;
  WHILE ( ix <= LONG ( VALTO ) );
      IF ( SUBST (VALTO, ix , 1 ) @= '0' );

          nCount = nCount + 1;

      else;
       ix  = 999999;
      endif;    

 ix = ix+ 1;
end;

IF ( nCount > 0 );
   sVALTO = DELET ( VALTO, 1, nCount );
 ELSE;
    sVALTO =  VALTO;
    
 ENDIF;  





sChildDescr = SUBSETNAME | ' - ' | CHILDDESCRIPT;
sParentDescr = SETNAME | ' - ' | DESCRIPT ;

#### ---- Uncomment once Child Description is added to source file.
AttrPutS ( sChildDescr, sDim, SUBSETNAME, 'CAPTION' );
AttrPutS ( CHILDDESCRIPT, sDim, SUBSETNAME, 'Description' );
#### ----
AttrPutS ( sParentDescr, sDim, SETNAME, 'CAPTION' );
AttrPutS ( DESCRIPT, sDim, SETNAME, 'Description' );



sParentCount = CellGetS ( sCube, SUBSETNAME, 'All Lines', 'Parent Count (System)' );
nParentCount = StringToNumber ( sParentCount ) + 1;

sExist = '';
sCnt = '';
ix = 1;
   WHILE ( ix <= nParentCount );

       sPar = CellGetS ( sCube, SUBSETNAME, NumberToString ( ix ), 'Parent');

       IF ( sPar @= SETNAME );
          sExist = 'Yes';
          sCnt =  NumberToString ( ix );
       ENDIF;    

ix = ix + 1;
END;       

IF ( sExist @= '' );
    
 CellPutS ( SETNAME, sCube, SUBSETNAME,  numberToString ( nParentCount ), 'Parent' );

 CellPutS ( numberToString ( nParentCount ), sCube, SUBSETNAME,  'All Lines', 'Parent Count (System)' );
    
ENDIF;
    
#AttrPutS ( SETNAME, sDim, SUBSETNAME, 'Parent' );



AttrPutS ( SEQNR, sDim, SUBSETNAME, 'Sequence Number' );




# Add rows to the LineNo dimension
DimensionElementInsertDirect( sDimLineNo, '', sLine, 'N' );
DimensionElementComponentAddDirect( sDimLineNo, 'All Lines', sLine, 1);

# Update Cube Values
CellPutS (sVALFROM, sCube, SUBSETNAME, sLine, 'From Value' );
CellPutS (sVALTO, sCube, SUBSETNAME, sLine, 'To Value' );

