   ^ mBalance Sheet Detail: 
      USD';

ExecuteProcess ( 'Sys_Cube_View_Create',
'pCube', sSrcCube,
 'pView', sSrcView,
 'pFilter', sSrcFilter,
 'pSuppressZero', 1,
 'pSuppressConsol',1,
 'pSuppressRules', 1,
 'pDimensionDelim', '^',
 'pElementStartDelim', ':',
 'pElementDelim', '>',
