procedures.Data:
#****Begin: Generated Statements***
#****End: Generated Statements****

# Reset the  LOOP variables
sProcess = '';
sSource = '';
sHierName = '';

# Look through the SYS Hierarchy Control and setermine if Hierarchy defined in the cube is maintained from SAP
# If True ( sProcess @= 'Y') the hierarchy will be maintained
ix = 1;

 WHILE ( ix <= nHier );

     sIx = NumberToString ( ix) ;

     sSource = CellGetS ( 'SYS Hierarchy Control', sDim, sIx, 'Source' );

     IF ( sSource @= 'SAP');

      sHierName = CellGetS ( 'SYS Hierarchy Control', sDim, sIx, 'Hierarchy Name' );   

      IF( sHierName @= VERSN )   ;

       sProcess = 'Y';
          
       ix = nHier;   

      ENDIF;
         
     ENDIF;
     
 ix = ix + 1;
END;         
     

IF ( sProcess @= 'Y');

sCap = ERGSL | ' - ' |  TXT45;   


    sID = VERSN | '_' | ID;



 

     sParentID = VERSN | '_' | PARENT;

     # Convert ID to Item Description
     sChild = DimensionElementPrincipalName ( sRefDim, sID );
     sParent = DimensionElementPrincipalName ( sRefDim, sParentID );
     # Insert Child Hierarchy Element
     DimensionElementInsertDirect ( sDim, '', sChild, 'n'); 
     ATTRPUTS ( sCap, sDim, sChild, 'Caption' );

    # If element Type = R, don't add the Parent element
    # Insert Parent Hierarchy element and create rollup
    IF ( Type @<> 'R');    
      DimensionElementInsertDirect ( sDim, '', sParent, 'n');    
      DimensionElementComponentAddDirect ( sDim, sParent, sChild, 1 )  ;  

    ENDIF;
 
ENDIF;

