    ELSE;

    nHierCount = CellGetN ( 'SYS Hierarchy Control', sDim, 'All Hierarchies', 'Count (System)' );
  
     ix = 1;
    
       WHILE (ix <= nHierCount);
           
       sIx = NumberToString(ix); 

       sUnwind = CellGetS ( 'SYS Hierarchy Control', sDim, sIx, 'Unwind' );    

       IF ( sUnwind @= 'Yes' );
           
