nHierCount = CellGetN ( sSrcCube, Dimension, 'All Hierarchies', 'Count (System)' );

iixHier = 1;

while ( iixHier <= nHierCount );
Line = NumberToString(iixHier);

sSource = CellGetS ( sSrcCube, Dimension, Line, 'Source' );


    IF ( sSource @= 'SAP');
    

sHier = CellGetS ( sSrcCube, Dimension, Line, 'Hierarchy Name' );

ix = 1;

   WHILE ( ix <=  DIMSIZ ( sRefDim) );
       
    sElem = DIMNM ( sRefDim, ix );

    IF ( ELISANC ( sRefDim, sHier, sElem ) = 1 % sHier @= sElem );

      DimensionElementInsertDirect ( sTgtDim, '', sElem, 'C');

#      sParent = CellGetS ( '}ElementAttributes_' | sRefDim , sElem , 'Parent' );

       sParentCount = CellGetS ( sRefCube, sElem, 'All Lines', 'Parent Count (System)');
       nParentCount = StringToNumber ( sParentCount );

        
       sPar = '';
       sParent = ''; 
       ixPar = 1;

         WHILE ( ixPar <= nParentCount );

            sPar = CellGetS ( sRefCube, sElem, NumberToString ( ixPar), 'Parent');
            
              IF ( ELISANC ( sRefDim, sHier, sPar) = 1 % sHier @= sPar );

                sParent = sPar;

              ENDIF;

           ixPar = ixPar + 1;

         END;      


      IF ( sParent @<> '' );

          IF ( DIMIX (sTgtDim, sParent) = 0 );

             DimensionElementInsertDirect ( sTgtDim, '', sParent, 'C');

          ENDIF;

             DimensionElementComponentAddDirect ( sTgtDim, sParent, sElem, 1 );

      ENDIF;

       sCaption = CellGetS ( '}ElementAttributes_' | sRefDim , sElem , 'CAPTION' );  
       sSequenceNumber =  CellGetS ( '}ElementAttributes_' | sRefDim , sElem , 'Sequence Number' );  
       sDescription =  CellGetS ( '}ElementAttributes_' | sRefDim , sElem , 'Description' );  

      CellPutS ( sCaption, '}ElementAttributes_' | sTgtDim, sElem, 'Caption'); 
      CellPutS ( sDescription, '}ElementAttributes_' | sTgtDim, sElem, 'Description');  
      CellPutS ( sDescription, '}ElementAttributes_' | sTgtDim, sElem, 'Short Description');  
      CellPutS ( sSequenceNumber, '}ElementAttributes_' | sTgtDim, sElem, 'Sequence Number');  
      CellPutN ( StringToNumber(sSequenceNumber), '}ElementAttributes_' | sTgtDim, sElem, 'Order Adj');  
#      CellPutS ( sParent, '}ElementAttributes_' | sTgtDim, sElem, 'Parent');  

      #### ---- Look through SYS PL Account Hierarchy, add leaf accounts based on account ranges
      sMapExist = CellGetS ( sRefCube, sElem, '1', 'From Value' );

        IF ( sMapExist @<> '');

          ixLeaf = 1;

          WHILE ( ixLeaf <= CellGetN ( sRefCube, sElem, 'All Lines', 'Count (System)'));

           sRange =   CellGetS( sRefCube, sElem, NumberToString( ixLeaf ), 'Account Range' ); 

           IF ( sRange @= 'No');
               
           sFrom =     CellGetS( sRefCube, sElem, NumberToString( ixLeaf ), 'From Value' );

            IF ( DIMIX ( sTgtDim, sFrom) <> 0 );

             DimensionelementComponentAddDirect ( sTgtDim, sElem, sFrom, 1 );

            ENDIF;

           ELSEIF ( sRange @= 'Yes');               
               
            sPrefix = CellGetS ( sRefCube, sElem, NumberToString( ixLeaf ), 'Alpha Prefix');
            sFrom = CellGetS ( sRefCube, sElem, NumberToString( ixLeaf ), 'Numeric From');
            nFrom = StringToNumber ( sFrom );
            sTo = CellGetS ( sRefCube, sElem, NumberToString( ixLeaf ), 'Numeric To');
            nTo = StringToNumber ( sTo );
    
                ix2 = nFrom;

                 WHILE ( ix2 <= nTo );
          
                   sLeaf = sPrefix | NumberToString ( ix2 );

                   IF ( DIMIX (sTgtDim, sLeaf) <> 0 );
               
                    DimensionelementComponentAddDirect ( sTgtDim, sElem, sLeaf, 1 );
               
                   ENDIF;       
                 ix2 = ix2 + 1;
                END;    
            ENDIF;
         ixLeaf = ixLeaf + 1;
         END;     

               
    ENDIF;    
        
        
    ENDIF;

 ix = ix + 1;

END;  

    endif;
iixHier = iixHier + 1;
    end;

