# Source file

sSourceFolder = CellGetS( 'SYS Control', 'Source Folder', 'String' );

sSourceFile = sSourceFolder | pFile;

DataSourceNameForServer = sSourceFile;

# If Dimension don't exist create Dimension, 
#   else unwind Hierarchies defined in the SYS Hierarchy Control cube

IF ( DimensionExists( sDim ) = 0 );
   
    DimensionCreate( sDim );

    ELSE;

    nHierCount = CellGetN ( 'SYS Hierarchy Control', sDim, 'All Hierarchies', 'Count (System)' );
  
     ix = 1;
    
       WHILE (ix <= nHierCount);
           
       sIx = NumberToString(ix); 

       sUnwind = CellGetS ( 'SYS Hierarchy Control', sDim, sIx, 'Unwind' );    

         IF ( sUnwind @= 'Yes' );           
           
           
            sHierName =  CellGetS ( 'SYS Hierarchy Control', sDim, sIx, 'Hierarchy Name' );   

                      ExecuteProcess ( 'Sys_Dim_Hierarchy_Unwind_Consolidation'
                      ,'pDimension', sDim
                      ,'pConsol', sHierName
