AttrInsert( sDim, '', 'Valid From', 's');
AttrInsert( sDim, '', 'Valid To', 's');
AttrInsert( sDim, '', 'Lock Indicator', 's');


# Add Root element of All Hierarchy
DimensionElementInsertDirect( sDim, '', 'All Profit Center' , 'C');
DimensionElementInsertDirect( sDim, '', 'Profit Center Rollup Undefined' , 'C');

procedures.Data:
