nCount = 0;
sProfitCenter = '';

ix = 1;
  WHILE ( ix <= LONG ( PRCTR ) );
      IF ( SUBST (PRCTR, ix , 1 ) @= '0' );

          nCount = nCount + 1;

      else;
       ix  = 999999;
      endif;    

 ix = ix+ 1;
end;

IF ( nCount > 0 );
   sProfitCenter = DELET ( PRCTR, 1, nCount );
 ELSE;
