MinorErrorLogMax=-1;
sSrcCube = 'Below the Line Assessment';

sProc = GetProcessName();
sRand = NumberToString(Round(RAND()*1000));

IF ( pPeriod @= '' );
    
   sPeriod = CellGetS ( 'SYS Control', 'Close Period', 'String' );

 ELSEIF ( pPeriod @<> '' );

    sPeriod = pPeriod;

ENDIF;

#---- Create Source View
sSrcView = '}SYS_Src_' |sProc|'_'| sRand;

sSrcFilter = 
  'Scenario: ' | pScenario | '
   ^ Fiscal Period: ' | sPeriod | '
   ^ Cost Center: All Cost Center
   ^ Profit Center: All Profit Center
   ^ PL Account: All PL Account 
   ^ Below the Line Source: All Sources   
   ^ mBelow the Line Assessment: USD > USD Offset';


ExecuteProcess ( 'Sys_Cube_View_Create',
'pCube', sSrcCube,
 'pView', sSrcView,
 'pFilter', sSrcFilter,
 'pSuppressZero', 1,
 'pSuppressConsol',1,
 'pSuppressRules', 1,
 'pDimensionDelim', '^',
 'pElementStartDelim', ':',
 'pElementDelim', '>',
 'pDebug', 0 );

sDim = 'Profit Center';

SubsetDeleteAllElements ( sDim, sSrcView );
SubsetElementInsert ( sDim, sSrcView, 'All Profit Center', 1);

sDim = 'PL Account';

SubsetDeleteAllElements ( sDim, sSrcView );
SubsetElementInsert ( sDim, sSrcView, 'OPERABSORP', 1);

sDim = 'Below the Line Source';

SubsetDeleteAllElements ( sDim, sSrcView );
SubsetElementInsert ( sDim, sSrcView, 'All Sources', 1);

sDim = 'mBelow the Line Assessment';

SubsetDeleteAllElements ( sDim, sSrcView );
SubsetElementInsert ( sDim, sSrcView, 'USD Net Assess', 1);

ViewExtractSkipCalcsSet( sSrcCube, sSrcView, 0 );

#---- Assign Source View as TI data source
DataSourceType = 'VIEW';
DataSourceNameForServer = sSrcCube;
DataSourceNameForClient = sSrcCube;
DataSourceCubeView = sSrcView;

nErrCnt = 0;

sScenario = IF ( pScenario @= 'O/L', 'OL', pScenario );

sErrFolder = CellGetS( 'SYS Control', 'Exception File Folder', 'String' );

sErrFile = sErrFolder | 'Issue_BTLAsses_'| sScenario | '_' | sPeriod |'.csv';

DatasourceASCIIDelimiter = ',';

