            sMessage = 'The name of a dimension must follow a dimension delimiter (' | sDelimDim | ')';
            If( pDebug >= 1 );
              AsciiOutput( sDebugFile, sMessage );
            EndIf;
            ProcessQuit;
        EndIf;

