        If( SubsetExists( sDimension, sSubset ) = 1 );
            If ( pDebug >= 1 );
                 AsciiOutput( sDebugFile, 'Subset ' | sSubset | ' exists on dimension ' | sDimension | '. Deleting all elements' );
