# This process will remove all children from a specific target consolidation in the target dimension
# If recursive will also unwind all consolidations that are children of the target regardless of depth

# Note:
# - If consolidations are also used in unrelated hierarchies and recursive is selected this will result in
#   orphan consolidations in the other hierarchies


#-------------- Start: Process Message Logging
NumericGlobalVariable('DataMinorErrorCount');
NumericGlobalVariable('PrologMinorErrorCount');
NumericGlobalVariable('MetaDataMinorErrorCount');
NumericGlobalVariable('DataRecordCount'); 
DataRecordCount = 0;
NumericGlobalVariable('MetaDataRecordCount'); 
MetaDataRecordCount = 0;

sProc = GetProcessName();
nStartTime = Now();
sStartTime = TimSt(nStartTime, '\M \D, \Y  at \H:\i:\s \p');
sProcMsg = 'data.load.Sys_Process_Message';
sCubMessage = 'Sys_Process_Message';
sCubeControl = 'Sys_Control';

#User
IF(DIMIX('}Clients', TM1USER()) <>0);
sID = AttrS('}Clients', TM1User(), '}TM1_DefaultDisplayValue');
sUser = SubSt(sID, 17, Long(sID) - 16);

Else;

sUser = 'ADMIN';

EndIf;

sParam = 'pDimension: ' | pDimension|' & '|'pConsol:'|pConsol |' & '| 'pRecursive:'| NumberToString(pRecursive);

sProcEmail = 'Sys_Send_Email';

#-------------- End: Process Message Logging

### Constants ###

cProcess = 'Sys.Dim.Hierarchy.Unwind.Consolidation';
cTimeStamp = TimSt( Now, '\Y\m\d\h\i\s' );
sRandomInt = NumberToString( INT( RAND( ) * 1000 ));
cDebugFile = GetProcessErrorFileDirectory | cProcess | '.' | cTimeStamp | '.' | sRandomInt ;
cHierAttr = 'Bedrock.Descendant';
cAttrVal = 'Descendant';


### Initialise Debug ###

If( pDebug >= 1 );

  # Set debug file name
  sDebugFile = cDebugFile | 'Prolog.debug';

  # Log start time
  AsciiOutput( sDebugFile, 'Process Started: ' | TimSt( Now, '\d-\m-\Y \h:\i:\s' ) );

  # Log parameters
  AsciiOutput( sDebugFile, 'Parameters: pDimension : ' | pDimension );
  AsciiOutput( sDebugFile, '            pConsol    : ' | pConsol );
  AsciiOutput( sDebugFile, '            pRecursive : ' | NumberToString( pRecursive ) );

EndIf;


### Validate Parameters ###

nErrors = 0;

# Validate dimension
If( Trim( pDimension ) @= '' );
  nErrors = 1;
  sMessage = 'No dimension specified';
  If( pDebug >= 1 );
    AsciiOutput( sDebugFile, sMessage );
  EndIf;
  DataSourceType = 'NULL';
  ItemReject( sMessage );
EndIf;
If( DimensionExists( pDimension ) = 0 );
  nErrors = 1;
  sMessage = 'Invalid dimension: ' | pDimension;
  If( pDebug >= 1 );
    AsciiOutput( sDebugFile, sMessage );
  EndIf;
  DataSourceType = 'NULL';
  ItemReject( sMessage );
EndIf;

# Validate consol
If( Trim( pConsol ) @= '' );
  nErrors = 1;
  sMessage = 'No consol specified';
  If( pDebug >= 1 );
    AsciiOutput( sDebugFile, sMessage );
  EndIf;
  DataSourceType = 'NULL';
  ItemReject( sMessage );
EndIf;
If( DimIx( pDimension, pConsol ) = 0 % DType( pDimension, pConsol ) @<> 'C' % ElCompN( pDimension, pConsol ) = 0 );

## Remove nErrors because we are unwinding some Consolidation elements that might not have children - Orphan is the main culprit
#  nErrors = 1;

  sMessage = 'Invalid consolidation: ' | pConsol | '. Not a C element or no children.';
  If( pDebug >= 1 );
    AsciiOutput( sDebugFile, sMessage );
  EndIf;
  DataSourceType = 'NULL';
## Remove the Item Reject because we are unwinding some Consolidation elements that might not have children - Orphan is the main culprit

##  ItemReject( sMessage );
EndIf;

### Turn-off Logging in the Attribute cube
sAttrCube = '}ElementAttributes_' | pDimension ;
IF ( CubeExists ( sAttrCube ) = 1 ) ;
    sOLogging = CELLGETS( '}CubeProperties', sAttrCube, 'Logging' );
    CELLPUTS( 'No', '}CubeProperties', sAttrCube, 'Logging' );
ENDIF ;


### Set Descendent attribute value

AttrDelete( pDimension, cHierAttr );
AttrInsert( pDimension, '', cHierAttr, 'S' );

nElementIndex = 1;
nElementCount = DimSiz( pDimension );
While( nElementIndex <= nElementCount );
  sElement = DimNm( pDimension, nElementIndex );
  If( ElIsAnc( pDimension, pConsol, sElement ) = 1 );
    AttrPutS( cAttrVal, pDimension, sElement, cHierAttr );
  EndIf;
  nElementIndex = nElementIndex + 1;
End;


### Remove direct children from the target consol ###

nChildren = ElCompN( pDimension, pConsol );

While( nChildren > 0 );
  # Unwind direct children of target hierarchy only
  sChild = ElComp( pDimension, pConsol, nChildren );
  If( pDebug <= 1 );
    DimensionElementComponentDeleteDirect( pDimension, pConsol, sChild );
  EndIf;
  nChildren = nChildren - 1;
End;


### Assign data source ###

If( pRecursive = 1 & pDebug <= 1 );
  # Assign Data Source
  DataSourceType = 'SUBSET';
  DatasourceNameForServer = pDimension;
  DatasourceNameForClient = pDimension;
  DatasourceDimensionSubset = 'ALL';
Else;
  # No data source, straight to Epilog
  DataSourceType = 'NULL';
EndIf;

