#****Begin: Generated Statements***
#****End: Generated Statements****

#AsciiOutPut ( 's:\prod\OXYChem\logs\test_MetaStart.txt', '1');

### Check for errors in prolog ###

If( nErrors <> 0 );
  ProcessBreak;
EndIf;


### Break all parent/child links below target consol ###

If( ElLev( pDimension, vElement ) = 0 );
  ItemSkip;
EndIf;

If( AttrS( pDimension, vElement, cHierAttr ) @= cAttrVal & DType( pDimension, vElement ) @= 'C' & ElCompN( pDimension, vElement ) > 0 );
  nChildren = ElCompN( pDimension, vElement );
  While( nChildren > 0 );
    sChild = ElComp( pDimension, vElement, nChildren );
    If( pDebug <= 1 );
      DimensionElementComponentDeleteDirect( pDimension, vElement, sChild );
    EndIf;
    nChildren = nChildren - 1;
  End;
EndIf;

#-------------- Start: Process Message Logging
MetaDataRecordCount = MetaDataRecordCount + 1;
#-------------- End: Process Message Logging

### End Metadata ###

procedures.Epilog:
