    #       up with the same number twice in seperate process executions
     If( SubsetExists( pDimension, cTempSubset ) = 1 );
      SubsetDestroy( pDimension, cTempSubset );
    EndIf;
   SubsetCreateByMDX( cTempSubset, sMDXExpr );

   SubsetElementDelete( pDimension , cTempSubset , 1 );

    ExecuteProcess( 'Sys_Dim_Sub_Clone'
      , 'pDimension' , pDimension
      , 'pSourceSub' , cTempSubset
      , 'pTargetSub' , pSubset
      , 'pDebug' , pDebug
    );

  EndIf;

EndIf;
IF(pAlias@='Yes');
    SubsetAliasSet( pDimension, pSubset, pAliasName ) ;
ELSE ;
    ATTRINSERT ( pDimension , '' , 'Temp' , 'A' ) ;
    SubsetAliasSet ( pDimension , pSubset , 'Temp' ) ;
    ATTRDELETE ( pDimension , 'Temp' ) ;
ENDIF;

