#--------------------------------------------------------
#--- Generic Process to clean orphan elements
#-   Orphan elements are elements not rolling up into 
#-   hiearchies defined in the SYS Hierarchy Control cube  
#--- Created: 05/14/2024
#### -- Changes:
#
#--------------------------------------------------------

MinorErrorLogMax=-1;
sProcess = GetProcessName();

# Create source subset
sSubset = '}SYS_Src_' | sProcess | '_' | pDimension;
IF ( SubsetExists( pDimension, sSubset  ) = 0 );
SubsetCreate (pDimension, sSubset );
ENDIF;
SubsetDeleteAllElements (pDimension, sSubset );

# Loop through all elements and add all elements without parents to a source subset
nElementCount = DimSiz( pDimension );
ix = 1;

WHILE( ix <= nElementCount );
  sElement = DIMNM( pDimension, ix );
  IF( ELPARN( pDimension,  sElement) = 0 );
    # Element with no parents
    SubsetElementInsert( pDimension,  sSubset, sElement, 1 );
  ENDIF;

  ix = ix + 1;
END;

# Assign subset as data source
DataSourceType='SUBSET';
DatasourceNameForServer= pDimension;
DatasourceDimensionSubset= sSubset;

# Number of Hiearchies defined in the SYS Hierarchy Control cube
nNumberOfHierarchies = CellGetN ( 'SYS Hierarchy Control', pDimension, 'All Hierarchies', 'Count (System)' );

procedures.Data:
#****Begin: Generated Statements***
#****End: Generated Statements****


# Add Orphan elements to Orphan Rollup

Root = 0;
ix =  1;

WHILE (ix <= nNumberOfHierarchies);
  sRootElement = CellGetS ( 'SYS Hierarchy Control', pDimension,  NumberToString (ix) , 'Hierarchy Name' );
  IF ( Element @= sRootElement );
    Root =  Root + 1;
  ENDIF;
  ix = ix + 1;
END;

IF ( Root = 0 );
  DimensionElementComponentAddDirect ( pDimension,  pDimension | ' Rollup Undefined', Element, 1);
ENDIF;

