#--------------------------------------------------------
#--- Process loads Actual data from the Profit and Loss Detail cube 
#--- into the Below the Line cube
#--- Admin users define Functional Areas loaded into 
#--- the Below the Line cube, by tagging the Below The Line (System)
#--- attribute on the Functional Area dimension
#--- Created: 07/08/2024
#### -- Changes:
# --- Added Below The Line (System) attribute filter 07/19/2024
# --- Remove Functional Area dimension from Below the Line cube 07/19/2024
# --- 11/13/24 - Updated process to key of updated Profit and Loss Detail cube
#--------------------------------------------------------


MinorErrorLogMax=-1;
sSrcCube = 'Profit and Loss Detail';
sTgtCube = 'Below the Line';
CellPutS('NO', '}CubeProperties', sTgtCube, 'LOGGING');

sProc = GetProcessName();
sRand = NumberToString(Round(RAND()*1000));



IF ( pStartPeriod @= '' );
    
   sStartPeriod = CellGetS ( 'SYS Control', 'Close Period', 'String' );

   sEndPeriod = ATTRS ( 'Fiscal Period', sStartPeriod, 'Next Period');

 ELSEIF ( pStartPeriod @<> '' );

    sStartPeriod = pStartPeriod;

    IF ( pEndPeriod @='' );

        ProcessQuit();

        ELSE;
    
       sEndPeriod =  pEndPeriod ;

    ENDIF;
        
 ELSE;

    ProcessQuit();

ENDIF;

#---- Create Source View
sSrcView = '}SYS_Src_' |sProc|'_'| sRand;

sSrcFilter = 
  '  Fiscal Period: ' | sStartPeriod | '
   ^ Functional Area: All Functional Area
   ^ Plant: All Plant
   ^ Profit Center: All Profit Center
   ^ Cost Center: All Cost Center   
   ^ PL Account: All PL Account 
   ^ Document No: All Document No
   ^ mProfit and Loss Detail: USD > Local';

ExecuteProcess ( 'Sys_Cube_View_Create',
'pCube', sSrcCube,
 'pView', sSrcView,
 'pFilter', sSrcFilter,
 'pSuppressZero', 1,
 'pSuppressConsol',1,
 'pSuppressRules', 1,
 'pDimensionDelim', '^',
 'pElementStartDelim', ':',
 'pElementDelim', '>',
 'pDebug', 0 );

#--- Filter only tagged Functional Areas to be loaded in BTL cube
sDim = 'Functional Area';
SubsetDeleteAllElements ( sDim, sSrcView );

ix = 1;

  WHILE ( ix <= ELCOMPN (sDim, 'All Functional Area' ) );

      sFA = ELCOMP ( sDim, 'All Functional Area', ix );
      sBTLFA = ATTRS ( sDim, sFA, 'Below the Line (System)' );

      IF ( sBTLFA @<> '' );

          SubsetElementInsert ( sDim, sSrcView, sFA, 1 );

      ENDIF;    

 ix = ix + 1;

END;      

#-- Filter Fiscal Periods to load
sDim = 'Fiscal Period';
SubsetDeleteAllElements( sDim, sSrcView );

sStartPeriodIx = ATTRS ( sDim, sStartPeriod, 'Period Index');
nStartPeriodIx = StringToNumber ( sStartPeriodIx );

sEndPeriodIx = ATTRS ( sDim, sEndPeriod, 'Period Index');
nEndPeriodIx = StringToNumber ( sEndPeriodIx );

ix = nStartPeriodIx;

  WHILE ( ix <= nEndPeriodIx );

      SubsetElementInsert ( sDim, sSrcView, NumberToString(ix), 1 );

 ix = ix + 1;
      
END;   

#---- Assign Source View as TI data source
DataSourceType = 'VIEW';
DataSourceNameForServer = sSrcCube;
DataSourceNameForClient = sSrcCube;
DataSourceCubeView = sSrcView;

